#include <bits/stdc++.h>
using namespace std;
int main(){ifstream d("/work/grammar/fitting/dict4.bin",ios::binary);vector<string>dict;while(1){unsigned char len;d.read((char*)&len,1);if(!d)break;string s(len,'\0');d.read(s.data(),len);dict.push_back(s);}ifstream t("/work/grammar/fitting/tokens4.bin",ios::binary);t.seekg(0,ios::end);size_t n=t.tellg()/2;t.seekg(0);vector<uint16_t>tok(n);t.read((char*)tok.data(),n*2);vector<size_t>cnt(65536);for(auto c:tok)cnt[c]++;vector<int>order(65536),remap(65536);iota(order.begin(),order.end(),0);stable_sort(order.begin(),order.end(),[&](int a,int b){return cnt[a]>cnt[b];});vector<uint32_t>meta;vector<uint8_t>data;for(int i=0;i<65536;i++){auto&s=dict[order[i]];remap[order[i]]=i;meta.push_back((uint32_t(s.size())<<24)|data.size());data.insert(data.end(),s.begin(),s.end());}data.resize((data.size()+65)&~size_t(1));ofstream payload("/work/grammar/fitting/payload.inc");payload<<"static const uint32_t meta[] = {\n";for(int i=0;i<65536;i++){payload<<meta[i]<<",";if(i%16==15)payload<<"\n";}payload<<"};\nstatic const uint8_t data[] = {\n";for(size_t i=0;i<data.size();i++){payload<<unsigned(data[i])<<",";if(i%32==31)payload<<"\n";}payload<<"};\n";ofstream bin("/work/grammar/fitting/archive.bin",ios::binary);uint64_t h[]={0x314650424d415247ULL,99999986,n,data.size()};bin.write((char*)h,sizeof h);bin.write((char*)meta.data(),meta.size()*4);bin.write((char*)data.data(),data.size());for(auto c:tok){uint16_t id=remap[c];bin.write((char*)&id,2);}cout<<"raw dict "<<data.size()<<" tokens "<<n<<" archive "<<bin.tellp()<<"\n";}
